ALTER TABLE "payment_operations" DROP CONSTRAINT "operation_effect_valid";--> statement-breakpoint
ALTER TABLE "payment_operations" ADD CONSTRAINT "operation_effect_valid" CHECK (COALESCE(("payment_operations"."operation"->>'effect' = 'CAPTURE' AND "payment_operations"."operation"->>'target' = 'RELEASED') OR ("payment_operations"."operation"->>'effect' = 'VOID' AND "payment_operations"."operation"->>'target' IN ('RELEASED', 'REFUSED', 'EXPIRED', 'CANCELLED')) OR ("payment_operations"."operation"->>'effect' = 'REAUTHORIZE' AND "payment_operations"."operation"->>'previousState' IN ('HELD', 'DECIDING', 'WAITING') AND jsonb_typeof("payment_operations"."operation"->'requestedAt') = 'number'), false));
